// Special-livery aircraft — collectible "premium" airframes.
//
// Point-in-time SNAPSHOT scraped from the public TablePress table on
// https://airportwebcams.net/special-liveries/ (columns: Country, Airline,
// Aircraft Type, Registration, Description) on 2026-06-19 — 2043 unique
// registrations. The site adds/retires liveries over time, so this needs a
// periodic refresh: re-fetch that page (browser User-Agent + Accept headers,
// the server 406s default clients) and re-parse the `#tablepress-8` rows.
//
// Matching is by REGISTRATION, which sightings already store, so a card's
// special-livery status is derived at render time — no DB column, and it
// retroactively flags existing sightings. Mirrors lib/airports.ts / airlines.ts.

export type SpecialLivery = {
  reg: string; // registration as displayed, e.g. "OE-LBZ"
  airline: string;
  type: string;
  livery: string; // description / livery name
};

