export const SPECIAL_LIVERIES_COUNT = SPECIAL_LIVERIES.length;

/** Canonical key for matching: uppercase, alphanumerics only (OE-LBZ -> OELBZ). */
export function normalizeReg(reg: string | null | undefined): string {
  return (reg ?? "").toUpperCase().replace(/[^A-Z0-9]/g, "");
}

const BY_REG = new Map<string, SpecialLivery>(
  SPECIAL_LIVERIES.map((l) => [normalizeReg(l.reg), l] as const),
);

/** The special livery for a registration, or null if it isn't a known one. */
export function specialLivery(reg: string | null | undefined): SpecialLivery | null {
  const key = normalizeReg(reg);
  return key ? BY_REG.get(key) ?? null : null;
}

export function isSpecialLivery(reg: string | null | undefined): boolean {
  return specialLivery(reg) !== null;
}
